   d.Body["items"]=new JsonArray();d.Body["promotionCode"]=null;await tx.Save(d with {Version=d.Version+1});await tx.Save(new("Checkout",checkoutId,owner,1,stored),true);var order=stored.DeepClone().AsObject();order["id"]=orderId;await tx.Save(new("Order",orderId,owner,1,order),true);quote.Body["used"]=true;await tx.Save(quote with {Version=quote.Version+1});return new(body,201,1);});var checkout=r.Body.Text("checkoutId");var expires=DateTimeOffset.Parse(r.Body.Text("expiresAt"));if(expires>clock.GetUtcNow()){SetCookie(h,"kohami.checkout.read",checkout,expires);SetCookie(h,"kohami.checkout.pay",checkout,expires);}return Result(h,r);
